insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('mei-pinschal-boeoed-ned-dea-fiad-kriag-mit-da-luft', 'Mei Pinschal bööd ned, dea fiad Kriag mit da Luft!', '', '', '', 'Viecher und Tiernamen auf Wienerisch', 'Mein Pinscherl bellt nicht, der führt Krieg mit der Luft!', '[{"kategorie": "wörtlich", "text": "\"Mein Zwergpinscher bellt nicht, der führt Krieg mit der Luft!\"  2. Mein Zwergpinscher führt Krieg mit allem, was sich bewegt. Und mit allem, was nicht!  3. Mein Pinscher is wie ein bellender Flammenwerfer – nur halt kleiner und grantiger!"}]'::jsonb, ''),
  ('a-pinschal-im-zeignis-is-kaa-woeoeduntagaung', 'A Pinschal im Zeignis is kaa Wööduntagaung!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Ein Pinscherl im Zeugnis ist kein Weltuntergang!', '[{"kategorie": "wörtlich", "text": "\"Ein Fünfer im Zeugnis ist kein Weltuntergang!\"  2. Von einem [[Fleck]] im Zeugnis geht die Welt nicht unter!  3. Ein ''Nicht genügend'' im Zeugnis ist halt ''ne kleine Watschn - aber sicher kein Schädelbruch!"}]'::jsonb, ''),
  ('wem-a-pinschal-draan', 'wem a Pinschal draan', '', '', '', 'Wiener Sprüche, die sitzen!', 'jemandem mit beiden Fingern in die Nasenlöcher fahren und dann eine drehende Handbewegung machen', '[{"kategorie": "wörtlich", "text": "\"jemandem ein Nasenstupserl verpassen\""}, {"kategorie": "", "text": "\"jemandem eins auf den Rüssel geben\""}, {"kategorie": "", "text": "\"jemandem ein Nasenreiberl verpassen\""}, {"kategorie": "", "text": "\"jemandem einen Nasenstüber versetzen\""}]'::jsonb, ''),
  ('zoi-oda-i-draa-da-a-pinschal-duach-de-noosnfront-bis-auffe-in-dei-resthian', 'Zoi, oda I draa da a Pinschal duach de Noosnfront bis auffe in dei Resthian!', '', '', '', 'Wiener Gaunersprache', 'Zahle, oder ich dreh dir ein Pinscherl durch die Nasenfront bis rauf in dein Resthirn!', '[{"kategorie": "wörtlich", "text": "\"Entweder du zahlst oder ich dreh dir meine beiden Zeigefinger durch die Nasenlöcher bis rauf in dein Resthirn!\"  2. Zahl, oder ich stopf dir meine Finger durch die Zinken bis in dein Resthirn!  3. Alter, zahl, oder ich dreh dir mit den Fingern die Nase auf wie ein Marmeladeglas!"}]'::jsonb, 'wem a Pinschal draan'),
  ('des-is-a-pipifax-fia-mi', 'Des is a Pipifax fia mi!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das ist ein Pipifax für mich!', '[{"kategorie": "wörtlich", "text": "\"Das ist ein Klacks für mich!\"  2. Das ist für mich eine Kleinigkeit!\"  3. Das ist für mich ein Kinderspiel!"}]'::jsonb, ''),
  ('moch-weng-dem-pipifax-do-ned-so-a-taeata', 'Moch weng dem Pipifax do ned so a Täata!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Mach wegen dem Pipifax da nicht so ein Theater!', '[{"kategorie": "wörtlich", "text": "\"Reg dich wegen dieser Kleinigkeit doch nicht so auf!\"  2. Bleib ruhig, das ist doch nur eine Bagatelle!  3. Mach nicht so viel Aufhebens wegen so einer Lappalie!"}]'::jsonb, ''),
  ('da-broodn-woa-pipifein-gaunz-zoat-und-softich', 'Da Broodn woa pipifein - gaunz zoat und softich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Der Braten war pipifein - ganz zart und saftig!', '[{"kategorie": "wörtlich", "text": "\"Der Braten war ganz besonders fein – butterzart und wunderbar saftig!\"  2. Der Braten war top - – zart, aromatisch und wunderbar saftig!  3. Der Braten war wie aus dem Bilderbuch - butterweich, perfekt gewürzt, voll im Saft!"}]'::jsonb, ''),
  ('es-woara-pipifeina-frueuelingstoog-de-luft-kloa-da-himmae-blau-wia-gmoind', 'Es woara pipifeina Früülingstoog - de Luft kloa, da Himmä blau wia gmoind!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Es war ein pipifeiner Frühlingstag, die Luft klar, der Himmel blau wie gemalt!', '[{"kategorie": "wörtlich", "text": "\"Es war ein traumhafter Frühlingstag - die Luft frisch, der Himmel strahlend blau wie gemalt!\"  2. Ein wunderschöner Frühlingstag: klare Luft, blauer Himmel – wie aus dem Bilderbuch!  3. Die Sonne lachte vom Himmel, die Luft war rein – ein perfekter Frühlingstag!"}]'::jsonb, ''),
  ('i-sog-nua-aans-pipifein-do-gibds-nix-zum-meckan', 'I sog nua aans: pipifein, do gibds nix zum Meckan!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich sag nur eins: pipifein, da gibt''s nichts zu meckern!', '[{"kategorie": "wörtlich", "text": "\"Ich sag nur eins: tadellos, da gibt es rein gar nichts zu meckern!\"  2. Ganz ehrlich: Das war rundum gelungen, da gibt es überhaupt nichts zu beanstanden!  3. Kurz und bündig: makellos - da gibt''s nichts auszusetzen!"}]'::jsonb, ''),
  ('pipifein-drauf-sei', 'pipifein drauf sei', '', '', '', 'Wiener Sprüche, die sitzen!', 'pipifein drauf sein', '[{"kategorie": "wörtlich", "text": "\"ausgesprochen gut gelaunt sein\""}, {"kategorie": "", "text": "\"rundum gut drauf sein\""}, {"kategorie": "", "text": "[[leiwand]] drauf sein\""}]'::jsonb, 'Da Schääf woa heit pipifein drauf - so freindlich kennd ma eam sunst goa ned!'),
  ('da-schaeaef-woa-heit-pipifein-drauf-so-freindlich-kennd-ma-eam-sunst-goa-ned', 'Da Schääf woa heit pipifein drauf - so freindlich kennd ma eam sunst goa ned!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der Chef war heut pipifein drauf - so freundlich kennt man ihn sonst gar nicht!', '[{"kategorie": "wörtlich", "text": "\"Der Chef war heut richtig gut drauf – fast nicht wiederzuerkennen!\"  2. Der Chef war heute ausgesprochen gut gelaunt – so erlebt man ihn selten!  3. So entspannt und freundlich hat man den Chef schon lange nicht erlebt - wir haben alle nur gestaunt!"}]'::jsonb, 'pipifein drauf sei'),
  ('da-bua-is-heit-pipifein-auzoong-fost-wia-fiara-hochzeit', 'Da Bua is heit pipifein auzoong - fost wia fiara Hochzeit!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Bub ist heute pipifein angezogen – fast wie für eine Hochzeit!', '[{"kategorie": "wörtlich", "text": "\"Der Junge ist heute besonders schick gekleidet – als ginge er zur Hochzeit!\"  2. Der Kerl sieht heute besonders elegant aus – fast wie ein Bräutigam!  3. Der Knabe ist heute piekfein angezogen - den könnten wir gleich zur Hochzeit schicken!"}]'::jsonb, ''),
  ('gee-moch-ma-an-tiakischn-kaffee-in-da-piitschn', 'Gee, moch ma an tiakischn Kaffee in da Piitschn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Geh, mach mir einen türkischen Kaffee in der Pitschen!', '[{"kategorie": "wörtlich", "text": "\"Los, mach mir einen türkischen Kaffee im Kupferkännchen!\"  2. Komm, mach mir einen schönen türkischen Kaffee, so wie früher – im kleinen Kupfertöpfchen!  3. Wie wär’s mit einem echten türkischen Kaffee aus dem Cezve?"}]'::jsonb, ''),
  ('i-brauch-dringend-a-frische-piitschn', 'I brauch dringend a frische Piitschn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Ich brauche dringend eine frische Pitschen!', '[{"kategorie": "allg.", "text": "\"Ich brauche dringend ein frisches Kännchen Kaffee!\"  2. (sexuell): Ich brauche dringend eine frische [[Fut]]!  3. Ich brauche dringend was Frisches zum Durchschnackseln!"}]'::jsonb, ''),
  ('dera-ghearad-de-piitschn-moi-so-richtig-voigschbritzd', 'Dera ghearad de Piitschn moi so richtig voigschbritzd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der gehörte die Pitschen mal so richtig vollgespritzt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Frau sollte man die Vagina mal so richtig vollspritzen!\"  2. Was die da bräuchte, wär ein Mann, der ihr das [[Schwanzfutteral]] mal so richtig vollspritzt!  3. Dieser Tussi sollte man ihr Geschlechtsteil mal so richtig vollspritzen!"}]'::jsonb, ''),
  ('gee-moch-ma-an-tiakischn-kaffee-in-da-biitschn', 'Gee, moch ma an tiakischn Kaffee in da Biitschn!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Geh, mach mir einen türkischen Kaffee in der Bitschen!', '[{"kategorie": "wörtlich", "text": "\"Los, mach mir einen türkischen Kaffee im Kupferkännchen!\"  2. Komm, mach mir einen schönen türkischen Kaffee, so wie früher – im kleinen Kupfertöpfchen!  3. Wie wär’s mit einem echten türkischen Kaffee aus dem Cezve?"}]'::jsonb, ''),
  ('dera-ghearad-de-biitschn-moi-so-richtig-voigschbritzd', 'Dera ghearad de Biitschn moi so richtig voigschbritzd!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Der gehörte die Bitschen mal so richtig vollgespritzt!', '[{"kategorie": "wörtlich", "text": "\"Dieser Frau sollte man die Vagina mal so richtig vollspritzen!\"  2. Was die da bräuchte, wär ein Mann, der ihr das [[Schwanzfutteral]] mal so richtig vollspritzt!  3. Dieser Tussi sollte man ihr Geschlechtsteil mal so richtig vollspritzen!"}]'::jsonb, ''),
  ('dera-ghearad-de-kuendigung', 'Dera ghearad de Kündigung!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Der da gehörte die Kündigung!', '[{"kategorie": "wörtlich", "text": "\"Der da sollte man die Kündigung aussprechen!\"  2. Ihr müsste man sofort die Kündigungspapiere geben!  3. Diese Frau gehört gefeuert!"}]'::jsonb, ''),
  ('de-kiiwara-lossn-vueue-duachgee-owa-waunnsd-iwan-plafoo-geesd-bist-faellig', 'De Kiiwara lossn vüü duachgee - owa waunnsd iwan Plafoo geesd, bist fällig!', '', '', '', 'Wiener Gaunersprache', 'Die Kieberer lassen viel durchgehen - aber wenn du über den Plafond gehst, bist du fällig!', '[{"kategorie": "wörtlich", "text": "\"Die Bullen lassen viel durchgehen - aber wer die rote Linie überschreitet, wird eingelocht!\"  2. Die Cops drücken öfter mal ein Auge zu – aber wer übers Limit geht, landet im Bau!  3. Solange du den Plafond nicht knackst, lassen sie dich machen – aber wer drüber ist, wandert in den Knast!"}]'::jsonb, ''),
  ('aum-plafoo-pickn', 'aum Plafoo pickn', '', '', '', 'Wiener Sprüche, die sitzen!', 'am Plafond picken', '[{"kategorie": "wörtlich", "text": "\"an der Zimmerdecke kleben\""}, {"kategorie": "fig.", "text": "\"die Wände hochgehen (vor Wut)\""}, {"kategorie": "", "text": "\"an der Decke kratzen vor Wut\""}]'::jsonb, 'I woa ned nua saua, Oida, I bin aum Plafoo pickd vua lauta Zuan!'),
  ('i-woa-ned-nua-saua-oida-i-bin-aum-plafoo-pickd-vua-lauta-zuan', 'I woa ned nua saua, Oida, I bin aum Plafoo pickd vua lauta Zuan!', '', '', '', 'Wiener Gaunersprache', 'Ich war nicht nur sauer, Alter, ich bin am Plafond gepickt vor lauter Zorn!', '[{"kategorie": "wörtlich", "text": "\"Ich war nicht nur sauer, Alter, ich bin fast durch die Decke geschossen, so geladen war ich!\"  2. Ich bin nicht nur ausgerastet, Junge, ich hab am Plafond rotiert!  3. Alter, ich war so geladen, ich hab fast die Decke durchbohrt – mit’m Schädel voran!"}]'::jsonb, 'aum Plafoo pickn'),
  ('an-jeedn-deppn-soit-ma-a-plafoondal-aufsetzn-damit-eams-hian-ned-schdaendich-ausrinnd', 'An jeedn Deppn soit ma a Plafoondal aufsetzn, damit eams Hian ned schdändich ausrinnd!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Einem jeden Deppen sollte man ein Plafonderl aufsetzen - damit ihm s''Hirn nicht ständig ausrinnt!', '[{"kategorie": "wörtlich", "text": "\"Jedem Idioten sollte man einen Hut aufsetzen - damit ihm das Hirn nicht aus dem Kopf rinnt!\"  2. Jedem Trottel gehört ein Deckel aufgesetzt – sonst rinnt ihm die Grütze raus wie aus’m löchrigen Suppentopf!  3. Gebt jedem Dodel ein Hauberl – vielleicht bleibt dann endlich was im Schädel hängen!"}]'::jsonb, ''),
  ('de-hod-a-plafoondal-wiara-taunzparkett', 'De hod a Plafoondal wiara Taunzparkett!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die hat ein Plafonderl wie ein Tanzparkett!', '[{"kategorie": "wörtlich", "text": "\"Die hat einen so breiten Hintern, dass du darauf tanzen könntest!\"  2. Bei der kannst du auf dem Hintern Polka tanzen!  3. Die hat ein Hinterschiff, da könnt'' ein ganzes Regiment drauf exerzieren!"}]'::jsonb, ''),
  ('des-bauxal-plaerrd-wiar-aum-schbiiss', 'Des Bauxal plärrd wiar aum Schbiiss!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Das Bauxerl plärrt wie am Spieß', '[{"kategorie": "wörtlich", "text": "\"Das Baby schreit wie am Spieß!\"  2. Das kleine Ding brüllt wie verrückt!  3. Das Kind schreit sich die Seele aus dem Leib!"}]'::jsonb, ''),
  ('plaerr-ned-umanaund-sunst-schdopf-i-da-de-goschn', 'Plärr ned umanaund, sunst schdopf I da de Goschn!', '', '', '', 'Wiener Gaunersprache', 'Plärr nicht rum, sonst stopf ich dir die Goschn!', '[{"kategorie": "wörtlich", "text": "\"Hör auf zu brüllen, sonst stopf ich dir die Fresse!\"  2. Schrei nicht rum, sonst stopf ich dir ‘nen Lappen in die Backen!  3. Heul nicht so rum, sonst stopf ich dir gleich deine Pappen!"}]'::jsonb, ''),
  ('an-plaerra-mochn', 'an Plärra mochn', '', '', '', 'Wiener Sprüche, die sitzen!', 'einen Plärrer machen', '[{"kategorie": "wörtlich", "text": "\"einen lauten Schrei ausstoßen\""}, {"kategorie": "", "text": "\"einen Aufschrei tun\""}, {"kategorie": "", "text": "[[a Gschraa mochn]]"}]'::jsonb, 'Wias des Schbinnanviech gseeng hod, hods an Plärra gmochd, dass sogoa da Hund zsaummzuckd is!'),
  ('wias-des-schbinnanviech-gseeng-hod-hods-an-plaerra-gmochd-dass-sogoa-da-hund-zsaummzuckd-is', 'Wias des Schbinnanviech gseeng hod, hods an Plärra gmochd, dass sogoa da Hund zsaummzuckd is!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie sie das Spinnenviech gesehen hat, hat’s an Plärrer gemacht, dass sogar der Hund zusammengezuckt ist!', '[{"kategorie": "wörtlich", "text": "\"Als sie die Spinne sah, stieß sie einen so lauten Schrei aus, dass selbst der Hund erschrocken ist!\"  2. Beim Anblick der Spinne schrie sie derart laut auf, dass sogar der Hund zusammenzuckte!  3. Sie kreischte beim Anblick der Spinne so durchdringend, dass selbst der Hund die Ohren anlegte!"}]'::jsonb, ''),
  ('zwanzg-plaerra-san-ned-vueue-owa-fia-drei-bia-und-a-bussal-reicht-s', 'Zwanzg Plärra san ned vüü - owa fia drei Bia und a Bussal reicht''s!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Zwanzig Plärrer sind nicht viel - aber für drei Bier und ein Busserl reicht''s!', '[{"kategorie": "wörtlich", "text": "\"Zwanzig Euro sind nicht viel - aber für drei Bier und ein Busserl reicht''s!\"  2. Zwanzig Euro sind schnell weg – aber für drei Seidl und ein Bussi reicht’s alleweil!  3. Zwanzig Euro – wenig für die Welt, aber genug für drei Bier und ein kleines Glück!"}]'::jsonb, ''),
  ('de-blaazd-weng-an-jeedn-schaas', 'De blaazd weng an jeedn Schaas!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die blazt wegen jedem Schas!', '[{"kategorie": "wörtlich", "text": "\"Die bricht wegen jeder Kleinigkeit in Tränen aus!\"  2. Die heult wegen jedem Pipifax gleich los!  3. Die fängt immer gleich zu weinen an – ganz egal warum!"}]'::jsonb, ''),
  ('de-brauchsd-nua-schiif-auschaun-faungds-schoo-zum-plaazn-au', 'De brauchsd nua schiif auschaun, faungds schoo zum Plaazn au!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die brauchst du nur schief anzuschauen, fängt sie schon zum Plazen an!', '[{"kategorie": "wörtlich", "text": "\"Die brauchst du nur schief anzuschauen, fängt sie schon zum Weinen an!\"  2. Du musst sie nur schräg angucken, schon heult sie los!  3. Ein falscher Blick, und sie bricht schon in Tränen aus!"}]'::jsonb, ''),
  ('do-faung-i-glei-au-zum-blaazn', 'Do faung I glei au zum Blaazn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Da fang ich gleich an zum Blazen!', '[{"kategorie": "wörtlich", "text": "\"Da fange ich gleich an zu weinen!\"  2. \"Da heul ich gleich los!\"  3. \"Da brech ich gleich in Tränen aus!\""}]'::jsonb, ''),
  ('cafe-blechtuam', 'Café Blechtuam', 'das', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Café Blechturm', '[{"kategorie": "wörtlich", "text": "\"Café Blechturm\" (Determinativkompositum aus \"Blech\"=\"Blechurinal\" und \"Turm\"=\"Bedürfnisanstalt\")"}, {"kategorie": "allg., scherzhaft für", "text": "\"öffentliche Bedürfnisanstalt mit Trockenurinalen aus Blech\", \"öffentliche WC-Anlage mit Blechpissoirs\", \"öffentlicher Blechbunker zum Pinkeln\", [[Schiffodrom]]"}]'::jsonb, 'Schiffn gaungan bist friara ins Café Blechtuam - a Wiina Denkmoi da Notduaft!'),
  ('schiffn-gaungan-bist-friara-ins-cafe-blechtuam-a-wiina-denkmoi-da-notduaft', 'Schiffn gaungan bist friara ins Café Blechtuam - a Wiina Denkmoi da Notduaft!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Schiffen gegangen bist du früher ins Café Blechturm - ein Wiener Denkmal der Notdurft!', '[{"kategorie": "wörtlich", "text": "\"Pinkeln ging man früher ins Café Blechturm - ein Wiener Denkmal der Notdurft!\"  2. Wenn’s pressiert hat, war das Café Blechturm immer in der Nähe – die Wiener Version einer öffentlichen Bedürfnisanstalt!  3. Die Wiener nannten diese alte Toilettenanlage aus Blech früher liebevoll-ironisch ‚Café Blechturm‘ – ein Relikt unserer urbanen Hygienegeschichte!"}]'::jsonb, ''),
  ('griin-gschdrichana-blechtuam', 'griin gschdrichana Blechtuam', 'der', '', '', 'Wiener Wörter mit schillernder Geschichte', 'grün gestrichener Blechturm', '[{"kategorie": "hist., scherzhaft für", "text": "\"öffentliche Bedürfnisanstalt\" (außen grün gestrichen und innen mit Trockenurinalen \"aus Blech\" ausgestattet)"}, {"kategorie": "allg.", "text": "\"öffentliche WC-Anlage mit Blechpissoirs\", \"öffentliche Bedürfnisanstalt mit Trockenurinalen aus Blech\", \"öffentlicher Blechbunker zum Pinkeln\" [[Schiffodrom]]"}]'::jsonb, 'Friara is bei uns im Park a griin gschdrichana Blechtuam gschdaundn - des Wiina Denkmoi da Notduaft!'),
  ('friara-is-bei-uns-im-park-a-griin-gschdrichana-blechtuam-gschdaundn-des-wiina-denkmoi-da-notduaft', 'Friara is bei uns im Park a griin gschdrichana Blechtuam gschdaundn - des Wiina Denkmoi da Notduaft!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Früher ist bei uns im Park ein grün gestrichener Blechturm gestanden - das Wiener Denkmal der Notdurft!', '[{"kategorie": "wörtlich", "text": "\"Damals hat bei uns im Park noch der grüne Blechturm gestanden – das legendäre Wiener Klo für jedermann!\"  2. Der grüne Blechbunker im Park – das war in Wien unser Stammklo, lang bevor''s moderne City-WCs gegeben hat!  3. Früher stand bei uns im Park ein grüner Toilettenturm aus Blech – ein typisches Beispiel der damaligen Wiener Sanitärarchitektur!"}]'::jsonb, 'griin gschdrichana Blechtuam'),
  ('de-pissoaforoeoen-is-da-hausgeist-vom-maennaheisl-varrauchd-vagammaed-und-unsinkboa', 'De Pissoaforöön is da Hausgeist vom Männaheisl - varrauchd, vagammäd und unsinkboa!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Die Pissoirforelle ist der Hausgeist vom Männerhäusl - verraucht, vergammelt und unsinkbar!', '[{"kategorie": "wörtlich", "text": "\"Die Pissoirforelle ist wie der Hausgeist von’m Männerklo – stinkt, gammelt und geht nie unter!\"  2. Die Klo-Kaulquappe – der letzte Stammgast am Kachelrand. Kaltgezogen, vergilbt und unsinkbar!  3. Die Pissoirforelle ist das spirituelle Totemtier jeder Männertoilette – verqualmt, vergilbt, vergessen, aber unsinkbar!"}]'::jsonb, ''),
  ('pockts-ollas-aum-pleedara-daunn-bleibd-da-koffaraum-frei', 'Pockts ollas aum Pleedara, daunn bleibd da Koffaraum frei!', '', '', '', 'Wiener Mechaniker-Slang', 'Packt alles auf den Plederer, dann bleibt der Kofferraum frei!', '[{"kategorie": "wörtlich", "text": "\"Packt alles auf den Dachgepäckträger, dann bleibt der Kofferraum frei!\"  2. Ladet alles auf den Dachträger, damit der Kofferraum frei bleibt!  3. Verstaut das ganze Gepäck oben in der Dachbox – dann bleibt der Innenraum leer!"}]'::jsonb, ''),
  ('den-pleedara-sei-auto-hod-mea-ps-ois-sei-hian', 'Den Pleedara sei Auto hod mea PS ois sei Hian!', '', '', '', 'Wiener Mechaniker-Slang', 'Das Auto von diesem Plederer hat mehr PS als sein Hirn!', '[{"kategorie": "wörtlich", "text": "\"Das Auto von diesem Raser hat mehr PS als sein Hirn!\"  2. Dieser Autoraser hat mehr PS unter der Motorhaube als in seinem Schädel!  3. Dieser Tempobolzer hat Turbo im Motor, aber nix im Hirn!"}]'::jsonb, ''),
  ('oida-waassd-wos-fiaran-pleedara-gmochd-hod-wia-ma-dea-hint-einegfoan-is', 'Oida, waassd wos fiaran Pleedara gmochd hod, wia ma dea hint einegfoan is?', '', '', '', 'Wiener Mechaniker-Slang', 'Alter, weißt du, was es für einen Plederer gemacht hat, wie der mir hinten reingefahren ist?', '[{"kategorie": "wörtlich", "text": "\"Alter, du kannst dir nicht vorstellen, was es für einen Knall gemacht hat, als der mir hinten reingefahren ist?\"  2. Alter, weißt du, was es für einen Kracher gemacht hat, als der mir hinten reingedonnert ist?  3. Alter, du glaubst nicht, wie’s gescheppert hat, als der mir hinten reingekracht ist!"}]'::jsonb, ''),
  ('bei-so-an-pleedara-hueuefd-ned-amoi-mea-a-schiam', 'Bei so an Pleedara hüüfd ned amoi mea a Schiam!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Bei so einem Plederer hilft nicht einmal mehr ein Schirm!', '[{"kategorie": "wörtlich", "text": "\"Bei so einem Regenguss hilft nicht einmal mehr ein Schirm!\"  2. Bei diesem Platzregen nützt selbst ein Schirm nichts mehr!  3. Bei diesem Wolkenbruch wird man trotz Schirm klatschnass!"}]'::jsonb, ''),
  ('den-sei-pleedara-is-im-goi-eigschloong-wiara-gronoodn', 'Den sei Pleedara is im Goi eigschloong wiara Gronoodn!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'Der Plederer von ihm ist im Goal eingeschlagen wie eine Granate', '[{"kategorie": "wörtlich", "text": "\"Sein Hammerschuss ist im Tor eingeschlagen wie eine Granate!\"  2. Sein wuchtiger Vollspannschuss hat sich regelrecht durchs Netz gebohrt!  3. Sein strammer Schuss schlug wie ein Projektil im Kasten ein – keine Chance für den Keeper!"}]'::jsonb, ''),
  ('ea-hod-an-pleedara-aussedunnat-wia-da-trommla-von-de-wiina-philharmonika', 'Ea hod an Pleedara aussedunnat wia da Trommla von de Wiina Philharmonika!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Er hat einen Plederer rausgedonnert wie der Trommler von den Wiener Philharmonikern!', '[{"kategorie": "wörtlich", "text": "\"Der hat einen krachen lassen wie der Trommler von den Wiener Philharmonikern!\"  2. Der hat einen Paukenschlag losgelassen wie der Trommler von den Wiener Philharmonikern!  3. Der hat einen rausgeballert wie der Trommler von den Wiener Philharmonikern bei Beethovens Neunter!"}]'::jsonb, ''),
  ('letzte-nochd-hauma-zu-dritt-pleedad-si-ia-freindin-und-i', 'Letzte Nochd hauma zu dritt pleedad - si, ia Freindin und I!', '', '', '', 'Sex, Erotik und Bettgeflüster auf Wienerisch', 'Letzte Nacht haben wir zu dritt geplödert - sie, ihre Freundin und ich!', '[{"kategorie": "wörtlich", "text": "\"Letzte Nacht haben wir''s zu dritt krachen lassen - sie, ihre Freundin und ich!\"  2. Letzte Nacht haben wir zu dritt miteinander geschlafen – sie, ihre Freundin und ich!  3. Gestern Nacht hatten wir ein Betthupferl zu dritt - sie, ihre Freundin und ich!"}]'::jsonb, ''),
  ('si-pleedad-oone-punkt-und-komma', 'Si pleedad oone Punkt und Komma!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sie plödert ohne Punkt und Komma!', '[{"kategorie": "wörtlich", "text": "\"Sie poltert ohne Punkt und Komma!\"  2. Sie geifert ohne Luft zu holen!  3. Die hört nie auf zu schnattern!"}]'::jsonb, ''),
  ('dea-pleedad-ind-hittn-eine-ois-warada-auf-da-flucht-vua-seina-oidn', 'Dea pleedad ind Hittn eine, ois warada auf da Flucht vua seina Oidn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Der plödert in die Hütte rein, als wäre er auf der Flucht vor seiner Alten!', '[{"kategorie": "wörtlich", "text": "\"Der kracht ins Wirtshaus rein, als wäre er auf der Flucht vor seiner Alten!\"  2. Der stürmt ins Beisl, als würde ihn seine Alte mit dem Nudelwalker verfolgen!  3. Der stürmt ins Wirtshaus, als wär ihm bei seiner Alten daheim die Luft zu dünn geworden!"}]'::jsonb, ''),
  ('dea-pleedad-aus-da-einfoat-ausse-oone-dassa-links-oda-rechts-schaud', 'Dea pleedad aus da Einfoat ausse, oone dassa links oda rechts schaud!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der plödert aus der Einfahrt raus, ohne dass er links oder rechts schaut!', '[{"kategorie": "wörtlich", "text": "\"Der schießt aus der Einfahrt raus, ohne dass er links oder rechts schaut!\"  2. Der kommt aus der Einfahrt rausgeschossen, ohne nach links und rechts zu schauen!  3. Der knallt blind raus aus der Einfahrt, als wär er allein auf der Welt!"}]'::jsonb, ''),
  ('dea-pleedad-an-ausse-wia-da-trommla-von-de-wiina-philharmonika', 'Dea pleedad an ausse wia da Trommla von de Wiina Philharmonika!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der plödert einen raus wie der Trommler von den Wiener Philharmonikern!', '[{"kategorie": "wörtlich", "text": "\"Der lässt einen krachen wie der Trommler von den Wiener Philharmonikern!\"  2. Der lässt einen Paukenschlag los wie der Trommler von den Wiener Philharmonikern!  3. Der knallt einen raus wie der Trommler von den Wiener Philharmonikern bei Beethovens Neunter!"}]'::jsonb, ''),
  ('si-pleedad-drei-glaasln-prosecco-owa-wia-nix', 'Si pleedad drei Glaasln Prosecco owa wia nix!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Sie plödert drei Gläser Prosecco runter wie nix!', '[{"kategorie": "wörtlich", "text": "\"Sie kippt drei Gläser Prosecco runter wie nix!\"  2. Die haut drei Gläser Prosecco weg, als wär’s Wasser!  3. Die ballert sich drei Gläser Prosecco rein, bevor du überhaupt anstoßen kannst!"}]'::jsonb, ''),
  ('kaum-dass-da-easchde-blitz-aufgleichd-is-hods-a-scho-owapleedad', 'Kaum dass da easchde Blitz aufgleichd is, hods a scho owapleedad!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Kaum dass der erste Blitz aufgeleuchtet ist, hat''s auch schon runtergeplödert!', '[{"kategorie": "wörtlich", "text": "\"Sobald der erste Blitz zu sehen war, hat es auch schon wie aus Kübeln gegossen!\"  2. Kaum war der erste Blitz da, ist der Regen auch schon wie aus Eimern auf uns heruntergeprasselt!  3. Mit dem allerersten Blitz öffnete der Himmel auch schon seine Schleusen!"}]'::jsonb, ''),
  ('kaum-dass-da-easchde-blitz-aufgleichd-is-hods-a-scho-pleedad', 'Kaum dass da easchde Blitz aufgleichd is, hods a scho pleedad!', '', '', '', 'Wiener Sprüche, die sitzen!', 'Kaum dass der erste Blitz aufgeleuchtet ist, hat''s auch schon geplödert!', '[{"kategorie": "wörtlich", "text": "\"Sobald der erste Blitz zu sehen war, hat es auch schon wie aus Kübeln gegossen!\"  2. Kaum war der erste Blitz da, hat''s auch schon geschüttet!  3. Mit dem allerersten Blitz hat''s auch schon zu gießen begonnen wie aus Kübeln!"}]'::jsonb, ''),
  ('dea-pleedad-de-schdrossn-owa-wiara-gsengde-sau', 'Dea pleedad de Schdrossn owa wiara gsengde Sau!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der plödert die Straße runter wie eine gesengte Sau!', '[{"kategorie": "wörtlich", "text": "Der brettert die Straße runter wie ein Wahnsinniger!  2. Der prescht die Straße runter wie ein Wilder!  3. Der donnert die Straße runter wie ein Irrer!"}]'::jsonb, ''),
  ('foan-wiara-gsengde-sau', 'foan wiara gsengde Sau', '', '', '', 'Wiener Sprüche, die sitzen!', 'fahren wie eine gesengte Sau', '[{"kategorie": "wörtlich", "text": "\"fahren wie eine Sau, der man beim Schlachten gerade die Haut abbrennt\""}, {"kategorie": "fig.", "text": "\"fahren wie ein Wahnsinniger\""}, {"kategorie": "", "text": "\"wie ein Irrer dahinrasen\""}, {"kategorie": "", "text": "\"brettern wie der Teufel persönlich\""}, {"kategorie": "", "text": "[[pleschen wie ein Wilder]]"}]'::jsonb, 'Dea foad wiara gsengde Sau - woascheinlich tankda Red Bull schdott Diisl!'),
  ('dea-foad-wiara-gsengde-sau-woascheinlich-tankda-red-bull-schdott-diisl', 'Dea foad wiara gsengde Sau - woascheinlich tankda Red Bull schdott Diisl!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der fährt wie eine gesengte Sau - wahrscheinlich tankt er Red Bull statt Diesel!', '[{"kategorie": "wörtlich", "text": "\"Der rast wie der Teufel persönlich - als ob er Zündkerzen im Hintern hätte!\"  2. Der brettert dahin wie eine Rakete - Red Bull statt Sprit, und der Flügel wächst gleich mit!  3. Der fährt wie vom Teufel persönlich gejagt – wahrscheinlich hat er Koffein im Kühlwasser!"}]'::jsonb, 'foan wiara gsengde Sau'),
  ('da-gsengde-mit-da-maschin-draad-schoo-wiida-seine-rundn-ums-haus-und-olle-vuahaeng-woogln-mit', 'Da Gsengde mit da Maschin draad schoo wiida seine Rundn ums Haus - und olle Vuahäng woogln mit!', '', '', '', 'Wiener Mechaniker-Slang', 'Der Gesengte mit seiner Maschine dreht schon wieder seine Runden ums Haus – und alle Vorhänge wackeln mit!', '[{"kategorie": "wörtlich", "text": "\"Der Gummibrenner mit seiner Maschine dreht schon wieder seine Runden ums Haus – und alle Vorhänge wackeln mit!\"  2. Der Raser vom Dienst zieht schon wieder seine Ehrenrunden ums Haus - und der ganze Block vibriert mit!  3. Der Asphaltcowboy kurvt schon wieder ums Haus – und die Fensterscheiben tanzen Samba!"}]'::jsonb, ''),
  ('tua-no-a-blaeaedschn-solood-aum-toella-daunn-schauds-mea-gleich', 'Tua no a Bläädschn Solood aum Tölla - daunn schauds mea gleich!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Tu noch eine Bletschen Salat am Teller - dann schaut''s mehr gleich!', '[{"kategorie": "wörtlich", "text": "\"Tu noch ein großes Salatblatt auf den Teller - dann sieht''s gleich besser aus!\"  2. Leg noch ein großes Salatblatt dazu – da sieht der Teller gleich appetitlicher aus!  3. Schmeiß noch ein großes Salatblatt drauf - dann sieht der Teller nicht mehr so leer aus!"}]'::jsonb, ''),
  ('de-blaeaetschn-auf-da-waund-is-woascheinlich-a-schimmae', 'De Bläätschn auf da Waund is woascheinlich a Schimmä!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Die Bletschen auf der Wand ist wahrscheinlich ein Schimmel!', '[{"kategorie": "wörtlich", "text": "\"Der Riesenfleck auf der Wand ist wahrscheinlich Schimmel!\"  2. Bei der großflächigen Verfärbung an der Wand könnte es sich um Schimmel handeln!  3. Da gammelt was an der Wand – der eklige Fleck sieht aus wie Schimmel!"}]'::jsonb, ''),
  ('oida-schau-da-de-blaeaedschn-au-de-i-noochn-goeoesnschdich-aufgrissn-hob', 'Oida, schau da de Bläädschn au, de I noochn Göösnschdich aufgrissn hob!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Alter, schau dir die Bletschen an, die ich nach dem Gelsenstich aufgerissen habe!', '[{"kategorie": "wörtlich", "text": "\"Alter, schau mal, was der Mückenstich angerichtet hat – eine riesige Schwellung!\"  2. Boah, schau dir den Riesenfleck auf meiner Haut an - alles nur von einem einzigen Gelsenstich!  3. Junge, guck dir das mal an – ich hab ''ne richtige Beulenkugel vom Gelsenstich!"}]'::jsonb, ''),
  ('imma-waunn-i-stress-hob-wochsd-ma-a-blaeaedschn-auf-da-goschn', 'Imma waunn I Stress hob, wochsd ma a Bläädschn auf da Goschn!', '', '', '', 'Krank & kuriert auf Wienerisch', 'Immer wenn ich Stress habe, wächst mir eine Bletschen auf der Goschen!', '[{"kategorie": "wörtlich", "text": "\"Immer wenn ich Stress habe, wächst mir eine eklige Fieberblase auf dem Mund!\"  2. Kaum hab ich Stress, blüht mir wieder so ein hässlicher Herpes auf der Lippe!  3. Immer wenn ich unter Druck stehe, krieg'' ich diese riesige Fieberblase auf der Lippe!"}]'::jsonb, ''),
  ('schau-da-de-fette-blaeaedschn-au-de-i-beim-feiaweafestl-kriagd-hob', 'Schau da de fette Bläädschn au, de I beim Feiaweafestl kriagd hob!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schau dir die fette Bletschen an, die ich beim Feuerwehrfest gekriegt hab!', '[{"kategorie": "wörtlich", "text": "\"Schau mal, was für eine große Medaille ich beim Feuerwehrfest bekommen habe!\"  2. Sieh dir mal das massive Abzeichen an - hab ich beim Feuerwehrfest verliehen bekommen!  3. Schau, meine Brust ist jetzt hochdekoriert - beim Feuerwehrfest hat man mir ein dickes Ehrenzeichen verliehen!"}]'::jsonb, ''),
  ('a-blaeaedschn-reissn', 'a Bläädschn reissn', '', '', '', 'Wiener Sprüche, die sitzen!', 'eine Bletschen reißen', '[{"kategorie": "wörtlich", "text": "\"der Länge nach hinfallen\""}, {"kategorie": "", "text": "\"schwer stürzen\""}, {"kategorie": "", "text": "\"einen kompletten Abflug machen\""}, {"kategorie": "", "text": "[[eine Brezen reißen]]"}, {"kategorie": "", "text": "[[einen Stern reißen]]"}]'::jsonb, 'I bin auf da Eisplottn ausgrutschd und hob a muadstrumm Bläädschn grissn!'),
  ('i-bin-auf-da-eisplottn-ausgrutschd-und-hob-a-muadstrumm-blaeaedschn-grissn', 'I bin auf da Eisplottn ausgrutschd und hob a muadstrumm Bläädschn grissn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Ich bin auf der Eisplatte ausgerutscht und habe eine mordstrumm Bletschen gerissen!', '[{"kategorie": "wörtlich", "text": "\"Ich bin auf eine Eisplatte getreten und der Länge nach hingefallen!\"  2. Ich bin auf der Eisplatte ausgerutscht und habe einen kompletten Abflug gemacht! 3. Ich bin auf Glatteis ausgerutscht und lag sekundenschnell flach wie ''ne Palatschinke auf dem Boden!"}]'::jsonb, ''),
  ('de-haund-volla-blaeaedschn-haum', 'de Haund volla Bläädschn haum', '', '', '', 'Wiener Kartentipplerjargon', 'die Hand voller Plätschen haben', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"die Hand voller Stichkarten haben\""}, {"kategorie": "", "text": "\"ein großartiges Blatt in der Hand halten\""}, {"kategorie": "", "text": "[[De Haund volla Brotzn haum]]"}]'::jsonb, 'Waunn I de Haund volla Bläädschn hob, wiad nimma laung gfackld!'),
  ('waunn-i-de-haund-volla-blaeaedschn-hob-wiad-nimma-laung-gfackld', 'Waunn I de Haund volla Bläädschn hob, wiad nimma laung gfackld!', '', '', '', 'Wiener Kartentipplerjargon', 'Wenn ich die Hand voller Bletschen habe, wird nicht mehr lange gefackelt!', '[{"kategorie": "wörtlich", "text": "\"Wenn ich die Hand voller Stichkarten habe, wird nicht mehr lang gefackelt!\"  2. Wenn ich die Stichkarten auf der Hand hab, wird gleich schonungslos durchgezogen!  3. Wenn ich ein großartiges Blatt in der Hand halte, fackle ich nicht lange, sondern spiel durch, bis nix mehr steht!"}]'::jsonb, ''),
  ('de-haund-volla-brootzn-haum', 'de Haund volla Brootzn haum', '', '', '', 'Wiener Kartentipplerjargon', 'die Hand voller Pratzen haben', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"die Hand voller Stichkarten haben\""}, {"kategorie": "", "text": "\"ein großartiges Blatt in der Hand halten\""}, {"kategorie": "", "text": "[[De Haund volla Bläädschn haum]]"}]'::jsonb, 'Fiaran Solo-Walaad muassd a Haund volla Brootzn haum!'),
  ('solo-walaad', 'Solo-Walaad', 'der', '', '', 'Wiener Kartentipplerjargon', 'Solo-Valat', '[{"kategorie": "wörtlich, Kartenspielerjargon", "text": "\"Solo-Valat\" (hochrangige Ansage im Tarockspiel, bei der ein Spieler alle Stiche selbst gewinnen muss – ohne Partner und ohne Talonaufnahme)"}, {"kategorie": "", "text": "\"Stichspiel im Alleingang\", \"Tarockansage mit allen Stichen\", \"Ein-Mann-Valat\""}]'::jsonb, ''),
  ('fiaran-solo-walaad-muassd-a-haund-volla-brootzn-haum', 'Fiaran Solo-Walaad muassd a Haund volla Brootzn haum!', '', '', '', 'Wiener Kartentipplerjargon', 'Für einen Solo-Valat musst du eine Hand voller Pratzen haben!', '[{"kategorie": "wörtlich", "text": "\"Für einen Solo-Valat musst du eine Hand voller Stichkarten haben!\"  2. Wennst einen Solo-Valat spielen willst, brauchst du Karten, die richtig zünden!  3. Für einen Solo-Valat musst du viele sichere Stiche in der Hand halten!"}]'::jsonb, ''),
  ('de-soloodblaeaedschn-woa-so-grooss-dass-das-ois-sonnanseegl-vawendn-haest-kenna', 'De Soloodbläädschn woa so grooss, dass das ois Sonnanseegl vawendn häst kenna!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Die Salatbletschen war so groß, ich hätt sie als Sonnensegel verwenden können!', '[{"kategorie": "wörtlich", "text": "\"Das Salatblatt war so groß, dass ich es als Sonnensegel verwenden hätte können!\"  2. Das Salatblatt war größer als mein Teller – wie aus''m Dschungel!  3. Das Salatblatt war so riesig, damit hätt ich locker den Garten beschatten können!"}]'::jsonb, ''),
  ('pass-auf-in-da-gemueseobtaeulung-patrulliad-grod-da-blaeaedschnkiiwara', 'Pass auf - in da Gemüseobtäulung patrulliad grod da Bläädschnkiiwara!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Pass auf - in der Gemüseabteilung patroulliert gerade der Bletschenkieberer!', '[{"kategorie": "wörtlich", "text": "\"Achtung – in der Gemüseabteilung patroulliert gerade ein Kontrollorgan vom Marktamt!\"  2. Gib Acht - der ''Gemüse-Kontrolleur'' schleicht grad durch die Regale!  3. Pass auf - der ''Salat-Kommissar'' ist gerade auf Streife in der Gemüseabteilung!"}]'::jsonb, ''),
  ('waunnsd-frisches-griinzeich-wueuesd-muassd-zum-blaeaedschntandla-ums-eck-gee', 'Waunnsd frisches Griinzeich wüüsd, muassd zum Bläädschntandla ums Eck gee!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Wenn du frisches Grünzeug willst, musst du zum Bletschentandler ums Eck geh’n!', '[{"kategorie": "wörtlich", "text": "\"Wenn du frisches Grünzeug willst, musst du zum Gemüsehändler ums Eck gehen!\"  2. Richtig frisches Bio-Gemüse findest du nur beim Gemüsehändler an der Ecke!  3. Für knackiges Grünzeug ist der Gemüsestand nebenan die erste Adresse!"}]'::jsonb, ''),
  ('des-krejzy', 'Des krejzy!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das crazy!', '[{"kategorie": "wörtlich, Jugendjargon", "text": "\"Das ist crazy!\"  2. Das ist verrückt!  3. Ich fass es nicht!  4. Wahnsinn!"}]'::jsonb, ''),
  ('da-drop-woa-in-fuenf-sekundn-ausvakaufd-des-krejzy', 'Da Drop woa in fünf Sekundn ausvakaufd - des krejzy!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Der Drop war in fünf Sekunden ausverkauft - das crazy!', '[{"kategorie": "wörtlich", "text": "\"Bei Verkaufsstart war nach fünf Sekunden alles komplett ausverkauft – Wahnsinn!\"  2. Kaum war das Produkt verfügbar, war es auch schon wieder vergriffen - das ist verrückt!  3. Innerhalb von fünf Sekunden war die ganze Kollektion ausverkauft – ich fass es nicht!"}]'::jsonb, 'Des krejzy!'),
  ('guufy-aes-hell', 'guufy äs hell', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'goofy as hell', '[{"kategorie": "wörtlich, Jugendjargon", "text": "\"goofy as hell\""}, {"kategorie": "", "text": "\"extrem albern\""}, {"kategorie": "", "text": "\"maximal peinlich\""}, {"kategorie": "", "text": "\"zum Fremdschämen\""}]'::jsonb, ''),
  ('des-woa-ka-flex-des-woa-guufy-aes-hell', 'Des woa ka Flex, des woa guufy äs hell!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Das war kein Flex, das war goofy as hell!', '[{"kategorie": "wörtlich, Jugendjargon", "text": "\"Das war kein cooler Auftritt, das war einfach nur lächerlich!\"  2. Er wollte Eindruck schinden, aber das wirkte einfach nur peinlich!  3. Er dachte, das kommt cool rüber – das war aber eher zum Fremdschämen!"}]'::jsonb, 'guufy äs hell'),
  ('brudi-dee-is-a-smaesch-10-10', 'Brudi, dee is a Smäsch – 10/10!', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Bruder, die ist ein Smash - 10/10!', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Bruder, die Frau ist ein echter Volltreffer – glatte 10 von 10!\"  2. Junge, das Girl ist ein Sahneschnittchen – absoluter Hingucker!  3. Brudi, sie ist der Inbegriff von Wow – zehn von zehn mit Bonuspunkten!"}]'::jsonb, ''),
  ('smaesch-oda-pass', 'Smäsch oda pass?', '', '', '', 'Wiener Jugendsprache & Teenie-Talk', 'Smash oder pass?', '[{"kategorie": "wörtlich, Jugendsprache", "text": "\"Smash or pass?\"  2. \"Sahneschnittchen oder graue Maus?\"  3. \"Würdest du mit ihm/ihr schlafen oder nicht?\"  4. \"Weltklasse oder Durchschnitt?\"  5. \"Heiß oder nicht?\""}]'::jsonb, ''),
  ('da-plutza-vom-moakd-woa-so-grooss-i-haedad-eam-ois-sitzhocka-vawendn-kenna', 'Da Plutza vom Moakd woa so grooss - I hädad eam ois Sitzhocka vawendn kenna!', '', '', '', 'Botanik und Pflanzen auf Wienerisch', 'Der Plutzer vom Markt war so groß, ich hätte ihn als Sitzhocker verwenden können!', '[{"kategorie": "wörtlich", "text": "\"Der Kürbis vom Markt war so groß, ich hätte ihn als Sitzhocker verwenden können!\"  2. Der Kürbis vom Markt war so riesig, der hätte in jedem Wohnzimmer als Sitzgelegenheit durchgehen können!  3. Ein Riesenkürbis in dieser Dimension ist eher ein Möbelstück als ein Lebensmittel!"}]'::jsonb, ''),
  ('des-is-a-gscheida-plutza-do-geed-uandlich-wos-eine', 'Des is a gscheida Plutza - do geed uandlich wos eine!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Das ist ein g’scheiter Plutzer – da geht ordentlich was rein!', '[{"kategorie": "wörtlich", "text": "\"Das ist eine ordentliche Karaffe – da passt richtig viel hinein!\"  2. \"Ein Tonkrug für alle Fälle – damit kriegt man ''ne ganze Runde satt!\"  3. Der Glasballon im Korb ist riesig - da könntest du eine Forelle drin schwimmen lassen!"}]'::jsonb, ''),
  ('des-aanzige-liad-wos-dea-auf-sein-plutza-schbueuen-kau-is-des-liad-vom-schaeaewadn-blechkiiwae', 'Des aanzige Liad, wos dea auf sein Plutza schbüün kau, is des Liad vom schääwadn Blechkiiwä!', '', '', '', 'Wienerisches aus Musik, Kunst, Kultur & Medien', 'Das einzige Lied, das der auf seinem Plutzer spielen kann, ist das Lied vom scheppernden Blechkübel!', '[{"kategorie": "wörtlich", "text": "\"Das einzige Lied, das der auf seiner Kürbisgitarre spielen kann, ist das Lied vom scheppernden Blecheimer!\"  2. Er beherrscht auf seiner Kürbisgitarre nur eine einzige Melodie: die Hymne an den scheppernden Blecheimer!  3. Wenn der auf seiner Kürbisgitarre aufspielt, erinnert das akustisch an einen scheppernden Blechkübel!"}]'::jsonb, ''),
  ('in-da-eckn-schdeed-no-da-oide-plutza-von-meine-groossoeoetan-a-relikt-aus-de-siebzga', 'In da Eckn schdeed no da oide Plutza von meine Groossöötan - a Relikt aus de Siebzga!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'In der Ecke steht noch der alte Plutzer von meinen Großeltern - ein Relikt aus den 70ern!', '[{"kategorie": "wörtlich", "text": "\"In der Ecke steht noch der große, klobige Fernsehapparat meiner Großeltern - ein Relikt aus den 70ern!\"  2. In der Ecke steht noch die alte Riesenflimmerkiste meiner Großeltern – ein Überbleibsel aus den 70er-Jahren!  3. In der Ecke thront noch der Fernsehschrank meiner Großeltern – groß wie ein Kühlschrank, laut wie ein Staubsauger!"}]'::jsonb, ''),
  ('wuevueue-goeoed-soi-i-no-in-de-maroode-fiama-eineschdeckn', 'Wüvüü Gööd soi I no in de maroode Fiama eineschdeckn?', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wie viel Geld soll ich noch in die marode Firma reinstecken?', '[{"kategorie": "wörtlich", "text": "\"Wie viel Geld soll ich noch in die marode Firma reinschießen?\"  2. Wie viel Kapital soll ich noch in die kriselnde Firma reinbuttern?  3. Wie viel Geld soll ich denn noch in das sinkende Schiff reinpumpen, bevor sich da mal was bewegt?"}]'::jsonb, ''),
  ('den-plutza-do-drueuem-brauchst-goa-ned-easchd-froong-dea-hod-kan-tau-von-iagendwos', 'Den Plutza do drüüm brauchst goa ned easchd froong - dea hod kan Tau von iagendwos!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Den Plutzer da drüben brauchst du gar nicht erst zu fragen - der hat keinen tau von irgendwas!', '[{"kategorie": "wörtlich", "text": "\"Den Kürbiskopf da drüben brauchst du gar nicht erst zu fragen - der checkt genau gar nichts!\"  2. Spar dir die Mühe – bei dem Hohlkopf ist Hopfen und Malz verloren, a kannst du gleich einen Baum fragen!  3. Diesen Deppen brauchst du gar nicht erst zu fragen - das Einzige, was der weiß, ist wie man doof schaut!"}]'::jsonb, 'kan Tau von wos haum'),
  ('schiab-dein-plutza-do-weg-i-siich-nix', 'Schiab dein Plutza do weg - I siich nix!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Schieb deinen Plutzer da weg - ich sehe nichts!', '[{"kategorie": "wörtlich", "text": "\"Schieb deinen Kopf da zur Seite - ich kann nichts sehen!\"  2. \"Könntest du bitte den Kopf ein bisschen zur Seite nehmen? Ich seh nichts!\"  3. Schieb deinen [[Titus]] zur Seite - ich seh sonst nichts!"}]'::jsonb, ''),
  ('dea-hod-an-plutza-do-glaubsd-es-kummd-a-medizinboi-auf-schdoeoezn', 'Dea hod an Plutza - do glaubsd, es kummd a Medizinboi auf Schdöözn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der hat einen Plutzer - da glaubst du, es kommt ein Medizinball auf Stelzen!', '[{"kategorie": "wörtlich", "text": "\"Der hat so a Trumm von an Schädel – da glaubst du, es kommt ein Medizinball auf Stelzen!\"  2. Wenn der mit seinem Riesenschädel daherkommt, denkst du, der bringt seinen Globus gleich selber mit!  3. Sein Kopf schaut aus wie ein Ballon, der gehen gelernt hat!"}]'::jsonb, ''),
  ('do-hosd-wiida-an-sauwan-plutza-vabrochn', 'Do hosd wiida an sauwan Plutza vabrochn!', '', '', '', 'Wiener Gaunersprache', 'Da hast du wieder einen sauberen Plutzer verbrochen!', '[{"kategorie": "wörtlich", "text": "\"Da hast du wieder einen argen [[Bock]] geschossen!\"  2. Das war ja mal wieder ein Meisterstück der Unfähigkeit!  3. Da hast du wieder einen bösen Schnitzer begangen!  4. Das war wieder ein dicker Fehlschuss von dir!"}]'::jsonb, ''),
  ('i-hau-ma-jeede-frua-a-poa-plutzakean-in-mei-mueuesli', 'I hau ma jeede Frua a poa Plutzakean in mei Müüsli!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Ich hau mir jede Früh ein paar Plutzerkerne in mein Müsli!', '[{"kategorie": "wörtlich", "text": "\"Ich streu mir jeden Morgen ein paar Kürbiskerne in mein Müsli!\"  2. Ich toppe mein Müsli morgens immer mit ein paar Kürbiskernen auf!  3. Kein Frühstück ohne Kürbiskerne in meinem Müsli!"}]'::jsonb, ''),
  ('den-sei-plutzaschaeaedl-passt-in-kan-hoeoem-hechstns-in-an-kochtopf', 'Den sei Plutzaschäädl passt in kan Hööm - hechstns in an Kochtopf!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Sein Plutzerschädel passt in keinen Helm - höchstens in ''nen Kochtopf!', '[{"kategorie": "wörtlich", "text": "\"Sein Quadratschädel passt in keinen Helm – allerhöchstens in einen Gulaschtopf!\"  2. Sein Quadratschädel findet nur in einem Maurerkübel Platz – ein Helm ist hoffnungslos!  3. Für so einen Betonkopf gibt''s keinen Helm - der passt höchstens in einen Bauarbeiterkübel!"}]'::jsonb, ''),
  ('dea-plutzaschaeaedl-hod-a-hian-aus-beton-und-a-ego-wiara-obrissbian', 'Dea Plutzaschäädl hod a Hian aus Beton und a Ego wiara Obrissbian!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Plutzerschädel hat ein Hirn aus Beton und ein Ego wie ''ne Abrissbirne!', '[{"kategorie": "wörtlich", "text": "\"Dieser Sturschädel hat ein Hirn aus Beton und ein Ego wie ''ne Abrissbirne!\"  2. Dieser Querulant  läuft mit ’nem Zementschädel und ’ner Ego-Bombe durch die Gegend!  3. Der Panzerschädel ist stur wie ''ne Sau - bei dem beißt du auf Granit!"}]'::jsonb, ''),
  ('warada-a-mammut-miassada-si-fia-sein-quadraadschaeaedl-ned-so-schaaman', 'Warada a Mammut, miassada si fia sein Quadraadschäädl ned so schaaman!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Wäre er ein Mammut, müsste er sich für seinen Quadratschädel nicht so schämen!', '[{"kategorie": "wörtlich", "text": "\"Wäre er ein Mammut, müsste er sich für seinen Quadratschädel nicht schämen – er wäre dann ja auch ausgestorben!\"  2. Als Mammut würde so ein kantiger Betonkopf vielleicht noch durchgehen - aber wir leben ja nicht mehr in der Eiszeit!  3. Wäre er ein Mammut, würden die Weibchen Schlange stehen – aber heute ist so ein Quadratschädel eher ein evolutionärer Unfall!"}]'::jsonb, ''),
  ('sei-kopf-is-viaeckad-und-dicht-wia-beton-a-echta-quadraadschaeaedl-hoid', 'Sei Kopf is viaeckad und dicht wia Beton - a echta Quadraadschäädl hoid!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Sein Kopf ist viereckig und dicht wie Beton - ein echter Quadratschädel halt!', '[{"kategorie": "wörtlich", "text": "\"Kopf wie ''ne Kiste, Verstand wie Zement – ein typischer Dickschädel hat!\"  2. Kantiger Schädel und Beton im Hirn - mehr Sturkopf geht nicht!  3. So viereckig obenrum und so dicht innen drin – ein richtiger Betonkopf halt!"}]'::jsonb, ''),
  ('da-typ-hod-an-richtign-quadraadplutza-ois-warad-sei-schaeaedl-aus-beton-gossn', 'Da Typ hod an richtign Quadraadplutza - ois warad sei Schäädl aus Beton gossn!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Der Typ hat einen richtigen Quadratplutzer – als wäre sein Kopf aus Beton gegossen!', '[{"kategorie": "wörtlich", "text": "\"Der Typ hat einen richtigen Quadratschädel – als wäre sein Kopf direkt aus Beton gegossen worden!\"  2. Sein Quadratplutzer ist so kantig und wuchtig, als hätte ihn ein Bildhauer aus einem Felsblock geschlagen!  3. So ein Betonkopf – man könnte meinen, der kommt direkt aus dem Steinbruch!"}]'::jsonb, ''),
  ('dea-quadraadplutza-geed-da-so-laung-aufd-eia-bist-entweda-jo-soogsd-oda-ausn-fensta-schbringst', 'Dea Quadraadplutza geed da so laung aufd Eia, bist entweda ''Jo'' soogsd oda ausn Fensta schbringst!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Der Quadratplutzer geht dir so lange auf den Sack, bis du entweder ''Ja'' sagst oder aus dem Fenster springst!', '[{"kategorie": "wörtlich", "text": "\"Dieser sture Querulant geht dir so lange auf den Sack, bis du entweder zustimmst oder aus dem Fenster springst!\"  2. Dieser Betonkopf terrorisiert dich so lange, bis du entweder nachgibst oder den Verstand verlierst!  3. Dieser penetrante Dickschädel bohrt und bohrt, bis du kapitulierst oder Amok läufst!"}]'::jsonb, ''),
  ('i-plutzia-di-so-laung-bis-dei-fontanoeoen-zruck-auf-embryoschdoellung-schrumpfd', 'I plutzia di so laung, bis dei Fontanöön zruck auf Embryoschdöllung schrumpfd!', '', '', '', 'Wiener Gaunersprache', 'Ich plutziere dich so lange, bis deine Fontanelle zurück auf Embryostellung schrumpft!', '[{"kategorie": "wörtlich", "text": "\"Ich dresche dir so lange auf den Schädel, bis deine Fontanelle zurück auf Embryostellung schrumpft!\"  2. Ich zimmer dir so lange auf den Schädel, bis du wieder Fruchtwasser gurgelst!  3. Ich schlag dir die Birne so windelweich, dass dass du wieder durch den Geburtskanal musst!"}]'::jsonb, ''),
  ('kan-tau-von-wos-haum', 'kan Tau von wos haum', '', '', '', 'Wiener Sprüche, die sitzen!', 'keinen Tau von etwas haben', '[{"kategorie": "wörtlich", "text": "\"keinen blassen Schimmer von etwas haben\""}, {"kategorie": "", "text": "\"nicht die leiseste Ahnung von etwas haben\""}, {"kategorie": "", "text": "\"keinen Dunst haben\""}, {"kategorie": "", "text": "[[auf dem Schlauch stehen]]"}]'::jsonb, ''),
  ('bei-dem-antiblitzgneissa-is-hopfn-und-moiz-valuan-dea-denkt-min-sitzfleisch', 'Bei dem Antiblitzgneissa is Hopfn und Moiz valuan - dea denkt min Sitzfleisch!', '', '', '', 'Wiener Gefühlsäußerungen & Kult-Sager', 'Bei dem Antiblitzgneißer ist Hopfen und Malz verloren - der denkt mit''m Sitzfleisch!', '[{"kategorie": "wörtlich", "text": "\"Bei dem Nichtchecker ist Hopfen und Malz verloren - der denkt mit''m Sitzfleisch!\"  2. Dieser Antiblitzgneißer ist nicht mehr zu retten - bei dem sitzt das Gehirn in der Hose!  3. Mit diesem Langsamdenker ist nichts anzufangen - dem rinnt ''s Hirnschmalz aus''m Arsch!"}]'::jsonb, ''),
  ('waunn-da-wiat-in-wei-ins-glaasl-plutschn-lossd-kriag-i-feichte-lippn', 'Waunn da Wiat in Wei ins Glaasl plutschn lossd, kriag I feichte Lippn!', '', '', '', 'Trinken, Saufen & Tschechern auf Wienerisch', 'Wenn der Wirt den Wein ins Glasl plutschen lässt, krieg ich feuchte Lippen!', '[{"kategorie": "wörtlich", "text": "\"Wenn der Wirt den Wein ins Gläschen gluckern lässt, krieg ich feuchte Lippen!\"  2. Wenn der Wein aus der Hand des Wirten so perlend ins Glas plätschert, läuft mir das Wasser im Mund zusammen!  3. Wenn der Wirt den Wein ins Gläschen perlen lässt, zittern mir die Lippen vor Freude!"}]'::jsonb, ''),
  ('de-klaane-hod-kan-richtign-schbroochfoeoela-si-tuad-nua-a-wengl-plutschn', 'De Klaane hod kan richtign Schbroochfööla, si tuad nua a wengl plutschn!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Die Kleine hat keinen richtigen Sprachfehler, sie tut nur ein wenig plutschen!', '[{"kategorie": "wörtlich", "text": "\"Die Kleine hat keinen richtigen Sprachfehler, sie lispelt bloß ein wenig!\"  2. Nix Gravierendes – das Mädel hat bloß ’nen kleinen S-Fehler!  3. Die Kleine zischt halt ein bisschen beim Reden - aber ein Sprachfehler im eigentlichen Sinne ist das für mich nicht!"}]'::jsonb, ''),
  ('moch-zeaschd-de-poeoezung-featig-bevuasd-weida-ausschoin-tuast', 'Moch zeaschd de Pöözung featig, bevuasd weida ausschoin tuast!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Mach zuerst die Pölzung fertig, bevor du weiter ausschalen tust!', '[{"kategorie": "wörtlich", "text": "\"Mach zuerst die Stützkonstruktion fertig, dann kannst du mit dem Ausschalen weitermachen!\"  2. Erst pölzen, dann ausschalen – so wie immer!  3. Sichere die Decke durch eine vollständige Pölzung ab, bevor du mit dem Ausschalen beginnst!"}]'::jsonb, ''),
  ('soi-i-da-a-poeoezung-vapassn', 'Soi I da a Pöözung vapassn?', '', '', '', 'Wiener Gaunersprache', 'Soll ich dir eine Pölzung verpassen?', '[{"kategorie": "wörtlich", "text": "\"Soll ich dir eine Tracht Prügel verpassen?\"  2. \"Möchtest du, dass es knallt?\"  3. \"Willst du wirklich ''ne Portion Blei aufs Fell?\""}]'::jsonb, ''),
  ('de-poeoezung-woa-nuara-vuawoanung-beim-naechsdn-moi-gibds-blei-oomdrauf', 'De Pöözung woa nuara Vuawoanung - beim nächsdn Moi gibds Blei oomdrauf!', '', '', '', 'Wiener Gaunersprache', 'Die Pölzung war nur eine Vorwarnung - beim nächsten Mal gibt''s Blei obendrauf!', '[{"kategorie": "wörtlich", "text": "\"Die Tracht Prügel war nur eine Vorwarnung - beim nächsten Mal gibt''s Blei obendrauf!\"  2. Die Prügel waren nur ein kleiner Vorgeschmack – das nächste Mal regnet’s Blei!  3. Die Fäuste haben gesprochen – doch das war nur die Vorhut. Beim nächsten Mal fliegen die Patronen!"}]'::jsonb, ''),
  ('poeoezn1', 'pöözn1', '', '', '', 'Grundwortschatz Wienerisch', 'pölzen', '[{"kategorie": "wörtlich", "text": "\"pölzen\" (vom mittelhochdeutschen \"bolz\"=Stützpfosten\")"}, {"kategorie": "allg.", "text": "\"mit einem Pflock stützen\", \"durch Pfosten abstützen\" (Mauern, Decken, etc.), fest verankern, befestigen"}]'::jsonb, ''),
  ('easchd-poeoezn-daunn-ausschoin-so-wia-imma', 'Easchd pöözn, daunn ausschoin - so wia imma!', '', '', '', 'Handwerk und Beruf – so sagt''s der Wiener!', 'Erst pölzen, dann ausschalen – so wie immer!', '[{"kategorie": "wörtlich", "text": "\"Wie immer: erst pölzen, dann kommt die Schalung!\"  2. Vor dem Bau der Schalung muss abgestützt werden – wie immer!  3. Erst rammen, dann schalen – das übliche Procedere!"}]'::jsonb, ''),
  ('den-haums-poeoezn-miassn-sunst-haeda-de-marii-ned-aussegruckd', 'Den haums pöözn miassn, sunst häda de Marii ned aussegruckd!', '', '', '', 'Wiener Gaunersprache', 'Den haben sie pölzen müssen, sonst hätte er die Marie nicht rausgerückt!', '[{"kategorie": "wörtlich", "text": "\"Den mussten sie brutal verhauen, bis er die Knete rausgerückt hat!\"  2. Den mussten sie weichklopfen, bis die Kohle kam!  3. Die haben ihn grün und blau geprügelt, bis er den Flieder endlich rausgerückt hat!"}]'::jsonb, ''),
  ('da-pomfineebra-kummd-ned-waunnsd-brav-woasd-dea-kummd-waunnsd-beim-wiatn-aafoch-liing-bleibsd', 'Da Pomfineebra kummd ned, waunnsd brav woasd - dea kummd, waunnsd beim Wiatn aafoch liing bleibsd!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Der Pompfüneberer kommt nicht, wennst brav warst – der kommt, wennst beim Wirten einfach liegen bleibst!', '[{"kategorie": "wörtlich", "text": "\"Der Leichenbestatter kommt, wenn dich der Wirt nimmer aufweckt, sondern bloß zudeckt!\"  2. Brav sein schützt nicht – ''ne g’scheite Leber und ein starker Kreislauf schon eher. Sonst kommt der Leichenbestatter mitten im G’spritzen!  3. Den Pompfüneberer rufst du nicht – der kommt, wenn der Wirt dich aus Höflichkeit nicht mehr anspricht!"}]'::jsonb, ''),
  ('beim-pompfineebra-waassd-dea-kummd-ned-zum-reedn-der-kummd-zum-zuadeckn', 'Beim Pompfineebra waassd: Dea kummd ned zum Reedn, der kummd zum Zuadeckn!', '', '', '', 'Tod und Sterben auf Wienerisch', 'Beim Pompfüneberer weißt du: Der kommt nicht zum Reden, der kommt zum Zudecken!', '[{"kategorie": "wörtlich", "text": "\"Beim Bestatter weißt du: Der stellt keine Fragen – der bringt nur den Deckel mit!\"  2. Der Pompfüneberer kommt nicht, um Smalltalk zu machen – der kommt, wenn alles gesagt ist!  3. Der Popmfüneberer ist nicht der Mann fürs Wort – sondern der fürs letzte Schweigen!"}]'::jsonb, ''),
  ('im-oidn-wiin-woan-de-pompfineebara-friara-so-bekaunnt-wiad-fiaka-nua-eebm-fiad-letzte-foat', 'Im oidn Wiin woan de Pompfineebara friara so bekaunnt wiad Fiaka - nua eebm fiad letzte Foat!', '', '', '', 'Wiener Wörter mit schillernder Geschichte', 'Im alten Wien waren die Pompfüneberer früher so bekannt wie der Fiaker – nur eben für die letzte Fahrt!', '[{"kategorie": "wörtlich", "text": "Im Wien vergangener Tage waren die Bestattungsdienstleister so präsent wie die Fiaker – bloß dass sie nur in eine Richtung kutschierten!  2. Im alten Wien war der Fiaker das Bild des Lebens – der Pompfüneberer das Echo danach!  3. Der Wiener kannte zwei Kutschfahrten, die zählen: die erste mit dem Fiaker zur Hochzeit, die letzte mit dem Pompfüneberer zum Friedhof!"}]'::jsonb, ''),
  ('a-broodana-porree-mit-a-bissl-butta-und-muskat-is-a-ideale-beiloog-zu-fisch-und-geflueuegl', 'A broodana Porree mit a bissl Butta und Muskat is a ideale Beiloog zu Fisch und Geflüügl!', '', '', '', 'Wiener Küche & Gaumenfreuden', 'Gebratener Porree mit ein bisschen Butter und Muskat ist eine ideale Beilage zu Fisch oder Geflügel!', '[{"kategorie": "wörtlich", "text": "\"Gebratener Lauch mit etwas Butter und Muskat ist eine ideale Beilage zu Fisch oder Geflügel!\"  2. In Butter gebratener Porree mit Muskatnuss passt hervorragend zu Fisch oder Geflügel!  3. Porree, in etwas Butter angebraten und mit Muskat gewürzt, eignet sich bestens als Beilage zu hellem Fleisch oder Fisch!"}]'::jsonb, ''),
  ('dei-praepotente-oat-geed-ma-uandlich-aum-keks', 'Dei präpotente Oat geed ma uandlich aum Keks!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Deine präpotente Art geht mir ordentlich auf den Keks!', '[{"kategorie": "wörtlich", "text": "\"Deine präpotente Art geht mir tierisch auf den Nerv!\"  2. Dein arrogantes Gehabe geht mir echt auf den Sack!  3. Du und deine aufgeblasene Art kotzen mich einfach nur an!"}]'::jsonb, ''),
  ('waunnsd-no-amoi-auf-den-buam-hiipracksd-kaunnsd-wos-daleebm', 'Waunnsd no amoi auf den Buam hiipracksd, kaunnsd wos daleebm!', '', '', '', 'Echt wienerisch – so sagt man das in Wien!', 'Wenn du noch einmal auf den Buben hinprackst, kannst du was erleben!', '[{"kategorie": "wörtlich", "text": "\"Wenn du noch einmal auf den Buben hinschlägst, setzt''s was!\"  2. Wenn du dem Buben noch einmal eine runterhaust, kriegst du richtig Ärger!  3. Wenn du den Kleinen nochmal anrührst, kriegst du’s mit mir zu tun!"}]'::jsonb, ''),
  ('so-wia-dea-schi-foad-is-kaa-wunda-dass-eam-hiiprackd-hod', 'So wia dea Schi foad, is kaa Wunda, dass eam hiiprackd hod!', '', '', '', 'Wiener Fußballer- und Sportlerjargon', 'So wie der Ski fährt, ist es kein Wunder, dass es ihn hingeprackt hat!', '[{"kategorie": "wörtlich", "text": "\"So wie der Ski fährt, ist es kein Wunder, dass er hingeflogen ist!\"  2. Der ist gefahren wie eine gesengte Sau – da war’s nur eine Frage der Zeit, bis es ihn hinstreut!  3. So wie der Ski fährt, war der Sturz praktisch vorprogrammiert!"}]'::jsonb, ''),
